"""Public shell; member data and every action require a server-verified admin."""

from agent_intake_ui import owner

def render(root, layout):
    body = '''<section class="admin-title"><h1>Администрирование IPvX</h1><p>Пользователи, роли, доступ к обсуждениям и история действий.</p><a href="account.html">Моя учётная запись</a></section>
<section class="prose" id="admin-gate"><h2>Доступ администратора</h2><p id="admin-status" role="status" aria-live="polite">Проверяем права на сервере…</p><a id="admin-login" class="button" href="https://ipvx.org/auth/login?returnTo=/admin.html" hidden>Войти через Relcom ID</a><button id="admin-retry" class="button secondary" type="button" hidden>Проверить доступ ещё раз</button></section>
<div id="admin-private" hidden>
<section class="section admin-users" id="users"><div class="admin-section-heading"><div><h2>Пользователи портала</h2><p class="small">Подтверждённые аккаунты, которые открывали портал. Имя — из профиля; номер участника постоянный.</p></div><button id="admin-refresh" class="button secondary" type="button">Обновить</button></div>
<form id="admin-search" class="admin-search"><label for="member-search">Имя или номер участника<input id="member-search" name="search" maxlength="100" type="search" placeholder="Найти пользователя"></label><label for="member-access">Доступ<select id="member-access" name="access"><option value="all">Все пользователи</option><option value="active">Открыт</option><option value="blocked">Заблокирован</option></select></label><button class="button secondary" type="submit">Найти</button></form><p id="admin-users-status" role="status" aria-live="polite"></p>
<div class="admin-user-grid"><div class="admin-member-pane"><div id="admin-members"></div><button id="admin-members-more" class="button secondary" type="button" hidden>Показать ещё пользователей</button></div>
<section id="selected-user" class="admin-selection" hidden aria-labelledby="selected-user-heading"><h3 id="selected-user-heading" tabindex="-1">Выбранный пользователь</h3><p id="selected-user-name"></p><code id="selected-user-id"></code><p id="selected-user-summary" class="small"></p><a class="admin-back" href="#users">К списку пользователей ↑</a>
<form id="admin-role-form"><h4>Роль пользователя</h4><label for="admin-role">Роль<select id="admin-role" name="role"><option value="moderator">Модератор — проверка комментариев</option><option value="maintainer">Сопровождающий — отметка роли в проекте</option><option value="admin">Администратор — пользователи и роли</option></select></label><label for="admin-role-action">Действие<select id="admin-role-action" name="action"><option value="grant">Назначить роль</option><option value="revoke">Снять роль</option></select></label><label for="admin-role-reason">Причина изменения роли<textarea id="admin-role-reason" name="reason" rows="2" minlength="3" maxlength="1000" required></textarea></label><button class="button" type="submit">Применить роль</button><p id="admin-role-status" role="status" aria-live="polite"></p></form>
<form id="admin-access-form"><h4>Доступ к порталу</h4><p>Блокировка запрещает комментарии, голоса и административные действия. Публичные материалы остаются открыты. Учётная запись Relcom ID сохраняется.</p><label for="admin-access-reason">Причина изменения доступа<textarea id="admin-access-reason" name="reason" rows="2" minlength="3" maxlength="1000" required></textarea></label><button class="button secondary" id="admin-access-action" type="submit">Заблокировать участие</button><p id="admin-access-status" role="status" aria-live="polite"></p></form>
<p class="small">Роли портала не меняют формальный состав голосования по RFC, доступ к GitHub, моделям или машинам. Начальный администратор защищён от случайного удаления доступа.</p></section></div></section>
<section class="section"><div class="admin-section-heading"><div><h2>Комментарии на проверке</h2><p class="small">До публикации их видят автор и модераторы.</p></div><button id="admin-queue-refresh" class="button secondary" type="button">Обновить очередь</button></div><p id="admin-queue-status" role="status" aria-live="polite"></p><div id="admin-queue"></div><button id="admin-queue-more" class="button secondary" type="button" hidden>Показать ещё из очереди</button></section>
<section class="section"><div class="admin-section-heading"><div><h2>Журнал действий</h2><p class="small">Назначения ролей, блокировки и решения модерации с причинами.</p></div><button id="admin-audit-refresh" class="button secondary" type="button">Обновить журнал</button></div><p id="admin-audit-status" role="status" aria-live="polite"></p><div id="admin-audit"></div><button id="admin-audit-more" class="button secondary" type="button" hidden>Предыдущие действия</button></section>
</div>'''
    body = body.replace('<div id="admin-private" hidden>', '<div id="admin-private" hidden>' + owner())
    page = layout('participate.html', 'Администрирование', body).replace('<body>', '<body class="admin-page">')
    page = page.replace('</head>', '<link rel="stylesheet" href="assets/admin.css"><script src="assets/admin.js" defer></script><script src="assets/agent-intake.js" defer></script></head>')
    (root/'admin.html').write_text(page)
